import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Filter out derived features
    non_derived_mask = [t != 'derived' for t in feats.types]
    ids = [i for i, mask in zip(feats.ids, non_derived_mask) if mask]
    types = [t for t, mask in zip(feats.types, non_derived_mask) if mask]
    x = feats.x[:, [feats.column(fid) for fid in ids]]

    # Calculate effect sizes and p-values
    effects = []
    for i, fid in enumerate(ids):
        y1 = x[feats.y == 1, i].mean()
        y0 = x[feats.y == 0, i].mean()
        diff = y1 - y0
        t_stat, p_val = stats.ttest_ind(x[feats.y == 1, i], x[feats.y == 0, i])
        effects.append((fid, diff, abs(t_stat), p_val))

    # Sort by effect size and p-value
    effects.sort(key=lambda x: (-abs(x[1]), x[3]))

    # Identify correlated pairs
    corr_pairs = set()
    for i in range(len(ids)):
        for j in range(i+1, len(ids)):
            r, _ = stats.pearsonr(x[:, i], x[:, j])
            if abs(r) >= 0.6:
                corr_pairs.add((ids[i], ids[j]) if ids[i] < ids[j] else (ids[j], ids[i]))

    # Build clusters of correlated features
    clusters = []
    used = set()
    for i in range(len(ids)):
        if ids[i] in used:
            continue
        cluster = {ids[i]}
        used.add(ids[i])
        for j in range(len(ids)):
            if ids[j] in used:
                continue
            if (ids[i], ids[j]) in corr_pairs or (ids[j], ids[i]) in corr_pairs:
                cluster.add(ids[j])
                used.add(ids[j])
        clusters.append(list(cluster))

    # For each cluster, select the feature with highest effect size
    selected_features = set()
    for cluster in clusters:
        if len(cluster) > 1:
            # Select feature with strongest effect size in cluster
            best_fid = max(cluster, key=lambda fid: abs([e for e in effects if e[0] == fid][0][1]))
            selected_features.add(best_fid)
        else:
            selected_features.add(cluster[0])

    # Select top features based on effect size
    top_features = [fid for fid, _, _, _ in effects[:20]]  # Top 20 features

    # Remove duplicates and near-duplicates
    final_features = []
    seen = set()
    for fid in top_features:
        if fid in selected_features or len(final_features) < MAX_DRIVERS:
            # Check if this feature is too similar to already selected ones
            is_similar = False
            for selected_fid in final_features:
                if (selected_fid, fid) in corr_pairs or (fid, selected_fid) in corr_pairs:
                    is_similar = True
                    break
            if not is_similar and fid not in seen:
                final_features.append(fid)
                seen.add(fid)
                if len(final_features) >= MAX_DRIVERS:
                    break

    # Use all features with strong effects as predictors
    columns = [fid for fid in ids if abs([e for e in effects if e[0] == fid][0][1]) > 0.15]

    # Create products for top correlated pairs
    products = []
    for a, b in corr_pairs:
        if a in columns and b in columns:
            products.append((a, b))

    # Weighted score: sum of top features with effect sizes as weights
    loadings = {}
    for fid, effect_size, _, _ in effects:
        if fid in columns:
            loadings[fid] = effect_size

    # Return the design
    return Design(
        drivers=tuple(final_features[:MAX_DRIVERS]),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
